const fs = require\('fs'\);
const path = require\('path'\);
const { execSync } = require\('child_process'\);

const cwd = '/home/haseeb-raza/Desktop/physioguidance/frontend';

// Only fix page files in \(dashboards\) — component imports got wrongly changed
const pageFiles = execSync\(
  'find "src/app/[locale]/\(dashboards\)" -name "*.tsx"',
  { encoding: 'utf-8', cwd }
\).trim\(\).split\('\\n'\).filter\(Boolean\);

// Reverse the import path changes \(restore @/components/{name}-dashboard\)
const importFixes = [
  [/@\\/components\\/dashboard\\/manager/g, '@/components/course-manager-dashboard'],
  [/@\\/components\\/dashboard\\/instructor/g, '@/components/instructor-dashboard'],
  [/@\\/components\\/dashboard\\/student/g, '@/components/student-dashboard'],
  [/@\\/components\\/dashboard\\/support/g, '@/components/support-dashboard'],
  [/@\\/components\\/dashboard\\/finance/g, '@/components/finance-dashboard'],
  [/@\\/components\\/dashboard\\/admin/g, '@/components/admin-dashboard'],
];

let totalChanges = 0;
let changedFiles = [];

for \(const file of pageFiles\) {
  const filePath = path.join\(cwd, file\);
  if \(!fs.existsSync\(filePath\)\) continue;

  let content = fs.readFileSync\(filePath, 'utf-8'\);
  let original = content;

  for \(const [pattern, replacement] of importFixes\) {
    content = content.replace\(pattern, replacement\);
  }

  if \(content !== original\) {
    fs.writeFileSync\(filePath, content, 'utf-8'\);
    changedFiles.push\(file\);
    totalChanges++;
  }
}

console.log\('Fixed ' + totalChanges + ' files:'\);
changedFiles.forEach\(f => console.log\('  ' + f\)\);
